CREATE TABLE workspace_roles (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', template_key TEXT, clinical_scope TEXT, permissions TEXT NOT NULL DEFAULT '[]', active INTEGER NOT NULL DEFAULT 1, UNIQUE(organization_id,name));
CREATE TABLE membership_roles (membership_id TEXT NOT NULL REFERENCES memberships(id), role_id TEXT NOT NULL REFERENCES workspace_roles(id), PRIMARY KEY(membership_id,role_id));
ALTER TABLE memberships ADD COLUMN is_owner INTEGER NOT NULL DEFAULT 0;
ALTER TABLE memberships ADD COLUMN clinical_verified INTEGER NOT NULL DEFAULT 0;
ALTER TABLE memberships ADD COLUMN clinical_scopes TEXT NOT NULL DEFAULT '[]';
ALTER TABLE memberships ADD COLUMN clinical_review_reference TEXT NOT NULL DEFAULT '';
ALTER TABLE memberships ADD COLUMN access_expires_at TEXT;
ALTER TABLE users ADD COLUMN provider_support_verified INTEGER NOT NULL DEFAULT 0;
ALTER TABLE encounters ADD COLUMN note_kind TEXT NOT NULL DEFAULT 'general';
UPDATE memberships SET is_owner=1 WHERE EXISTS (SELECT 1 FROM audits a WHERE a.action='workspace.created' AND a.organization_id=memberships.organization_id AND a.actor_id=memberships.user_id) OR (role='administrator' AND NOT EXISTS (SELECT 1 FROM audits a WHERE a.action='workspace.created' AND a.organization_id=memberships.organization_id) AND id=(SELECT m.id FROM memberships m WHERE m.organization_id=memberships.organization_id AND m.role='administrator' ORDER BY m.id LIMIT 1));
UPDATE memberships SET clinical_verified=1,clinical_scopes='["general"]',clinical_review_reference='Existing verified clinical membership retained by migration 005' WHERE role='clinician' AND user_id IN (SELECT id FROM users WHERE verified=1);
